def _iter_entry_points(group: str):
    """Yield declared entry points for *group*, tolerating older ``importlib`` versions."""
    try:
        from importlib.metadata import entry_points
    except ImportError:  # pragma: no cover - Python < 3.8
        return
    try:
        all_entry_points = entry_points()
        if hasattr(all_entry_points, "select"):
            selected = all_entry_points.select(group=group)
        else:
            selected = all_entry_points.get(group, [])
    except Exception:
        return
    for entry_point in selected:
        yield entry_point


def _count_entry_points(group: str) -> int:
    """Count the entry points declared for *group*."""
    return len(list(_iter_entry_points(group)))


